import {startFlowPlayback} from './flow-playback.js?v=flow-20261005';
import {queueSceneModel} from './quality-scene-model.js';
export function simulateQueue({capacity=2,buffer=8,policy='fifo',baseDelay=20,burst=4}={}){
 if(!Number.isInteger(capacity)||capacity<1||capacity>8||!Number.isInteger(buffer)||buffer<1||buffer>32||!Number.isInteger(burst)||burst<0||burst>8||!Number.isFinite(baseDelay)||baseDelay<0||baseDelay>200||!['fifo','priority'].includes(policy))throw Error('ค่าของแบบจำลองอยู่นอกช่วง');
 const queue=[],sent=[],dropped=[],steps=[];let seq=0;
 for(let tick=0;tick<24;tick++){
  const incoming=tick<12?[...Array(burst)].map(()=>({id:++seq,kind:'file',arrive:tick})).concat({id:++seq,kind:'game',arrive:tick}):[];
  const lost=[];for(const packet of incoming){if(queue.length>=buffer){dropped.push(packet);lost.push(packet);}else queue.push(packet);}
  const outgoing=[];for(let slot=0;slot<capacity&&queue.length;slot++){
   let index=policy==='priority'?queue.findIndex(p=>p.kind==='game'):0;if(index<0)index=0;
   const packet=queue.splice(index,1)[0];packet.depart=tick;packet.delay=baseDelay+(tick-packet.arrive)*10+10;sent.push(packet);outgoing.push(packet);
  }
  steps.push({tick,incoming,outgoing,lost,queue:queue.map(p=>({...p}))});
 }
 const metrics=kind=>{const received=sent.filter(p=>p.kind===kind),lost=dropped.filter(p=>p.kind===kind),pending=queue.filter(p=>p.kind===kind),delays=received.map(p=>p.delay);return {received:received.length,lost:lost.length,pending:pending.length,throughput:received.length*8000/.24/1e6,delay:delays.length?delays.reduce((a,b)=>a+b,0)/delays.length:0,variation:delays.length>1?delays.slice(1).reduce((s,v,i)=>s+Math.abs(v-delays[i]),0)/(delays.length-1):0};};
 return {capacity,buffer,policy,baseDelay,burst,steps,sent,dropped,pending:queue,game:metrics('game'),file:metrics('file'),bandwidth:capacity*.8};
}
